      "SupportTicketScore": {
        "description": "Score based on support ticket volume. Higher volume indicates higher risk.",
        "calculation": "If SupportTickets <= 3, score = 1; If 3 < SupportTickets <= 5, score = 2; If 5 < SupportTickets <= 10, score = 3; If SupportTickets > 10, score = 4"
